import io.opentelemetry.api.baggage.BaggageEntryMetadata;
import io.opentelemetry.context.Context;
import io.opentelemetry.context.Scope;

/**
 * A mutable implementation of the OpenTelemetry {@link io.opentelemetry.api.baggage.Baggage} that is associated with a
 * single span.
 * <p>
 * Baggage entries can be added or updated using {@link #baggage(String, String)} without altering the OTel
 * {@link io.opentelemetry.context.Context}. The baggage becomes part of the context only when the owning span is
 * activated, at which point {@link #makeCurrent()} is invoked as part of establishing the span's scope.
 */
class MutableOpenTelemetryBaggage implements Baggage {

    private final Map<String, BaggageEntry> values = new HashMap<>();

    MutableOpenTelemetryBaggage() {
    }

    private MutableOpenTelemetryBaggage(Builder builder) {
        values.putAll(builder.values);
    }

    @Override
    public int size() {
        return values.size();
    }

    @Override
    public void forEach(BiConsumer<? super String, ? super BaggageEntry> consumer) {
        values.forEach(consumer);
    }

    @Override
    public Map<String, BaggageEntry> asMap() {
        return Collections.unmodifiableMap(values);
    }

    @Override
    public String getEntryValue(String entryKey) {
        BaggageEntry entry = values.get(entryKey);
        return entry != null ? entry.getValue() : null;
    }

    @Override
    public BaggageBuilder toBuilder() {
        return new Builder(values);
    }

    /**
     * Add or update a baggage entry without touching the OTel {@link io.opentelemetry.context.Context}.
     *
     * @param key   baggage key
     * @param value baggage value
     */
    void baggage(String key, String value) {
        values.put(key, new MutableEntry(value));
    }

    /**
     * Activate this baggage by storing it in the current OTel {@link io.opentelemetry.context.Context}.
     * <p>
     * This is intended to be called as part of activating the owning span so the baggage participates in the same
     * scope; the returned {@link io.opentelemetry.context.Scope} restores the previous context when closed.
     *
     * @return the OTel scope for this baggage
     */
    @Override
    public Scope makeCurrent() {
        return Context.current().with(this).makeCurrent();
    }

    private record MutableEntry(String value, BaggageEntryMetadata metadata) implements BaggageEntry {

        private MutableEntry(String value) {
            this(value, BaggageEntryMetadata.empty());
        }

        @Override
        public String getValue() {
            return value;
        }

        @Override
        public BaggageEntryMetadata getMetadata() {
            return metadata;
        }
    }

    private static final class Builder implements BaggageBuilder {

        private final Map<String, BaggageEntry> values;

        private Builder(Map<String, BaggageEntry> values) {
            this.values = new HashMap<>(values);
        }

        @Override
        public BaggageBuilder put(String key, String value, BaggageEntryMetadata entryMetadata) {
            values.put(key, new MutableEntry(value, entryMetadata));
            return this;
        }

        @Override
        public BaggageBuilder remove(String key) {
            values.remove(key);
            return this;
        }

        @Override
        public Baggage build() {
            return new MutableOpenTelemetryBaggage(this);
        }
